INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 2,'Привет, $N. Чем я могу тебе помочь?' FROM `npc_text` b WHERE b.`id`=2 AND BINARY b.`text0_1`=BINARY 'Hey there, $N. How can I help you?' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 737,'Ну здравствуй. Похоже, ты не прочь заработать немного монет, а? По глазам вижу. Я магнат Кебок, заведую делами в Азероте. Если ищешь богатства, возможно, я смогу что-нибудь устроить.' FROM `npc_text` b WHERE b.`id`=737 AND BINARY b.`text0_0`=BINARY 'Well, hello there. You seem like you wouldn\'t be opposed to making some coin, hm? I can tell from the look in your eyes. I am Mogul Kebok, overseer of operations in Azeroth, and if it is riches you seek, perhaps I can make arrangements.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 773,'$C, значит? Я Кразек, секретарь барона Ревилгаза. Я знаю все, что происходит в этих джунглях и за их пределами. Может, тебе интересно узнать нынешние цены на нефть в Кабестане? Нет? Или, может, ищешь работу? С этим я могу помочь.' FROM `npc_text` b WHERE b.`id`=773 AND BINARY b.`text0_0`=BINARY '$C, eh? I am Krazek, Baron Revilgaz\'s secretary. I know everything about the goings on in this jungle and beyond. Perhaps you\'d be interested in knowing the going price on oil in Ratchet? No? Looking for work, maybe? I can help you there.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 2498,'Что-что?!? Нам всем надо зарабатывать... а стоя без дела, прибыли не получишь.' FROM `npc_text` b WHERE b.`id`=2498 AND BINARY b.`text0_0`=BINARY 'What what?!?  We all have profit to make... and we won\'t do it by standing idle.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`) SELECT 4076,'Ренни теперь обитает в большом здании в центре города. Это самое большое здание в Брилле... Его очень трудно не заметить.' FROM `npc_text` b WHERE b.`id`=4076 AND BINARY b.`text2_0`=BINARY 'Innkeeper Renee has moved to the large building in the center of town.  It\'s the biggest building in Brill... Very hard to miss.' ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='',VALUES(`text2_0_loc8`),`text2_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`) SELECT 4076,'Ренни теперь обитает в большом здании в центре города. Это самое большое здание в Брилле... Его очень трудно не заметить.\n' FROM `npc_text` b WHERE b.`id`=4076 AND BINARY b.`text2_1`=BINARY 'Innkeeper Renee has moved to the large building in the center of town.  It\'s the biggest building in Brill... Very hard to miss.\n' ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='',VALUES(`text2_1_loc8`),`text2_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`) SELECT 4077,'Неужели меня можно принять за заклинателя? Впрочем, до меня дошли слухи, что Кейн Песнь Пламени теперь обитает в лаборатории и вечно занимается чем-то сомнительным.' FROM `npc_text` b WHERE b.`id`=4077 AND BINARY b.`text2_0`=BINARY 'Do I look to you like I cast spells?  Well, I did hear that Cain Firesong now hangs out in the laboratory, always working on something unsavory.' ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='',VALUES(`text2_0_loc8`),`text2_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`) SELECT 4077,'Неужели меня можно принять за заклинателя? Впрочем, до меня дошли слухи, что Кейн Песнь Пламени теперь обитает в лаборатории и вечно занимается чем-то сомнительным.' FROM `npc_text` b WHERE b.`id`=4077 AND BINARY b.`text2_1`=BINARY 'Do I look to you like I cast spells?  Well, I did hear that Cain Firesong now hangs out in the laboratory, always working on something unsavory.' ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='',VALUES(`text2_1_loc8`),`text2_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 6491,'Твое время еще не пришло. Я помогу тебе вернуться в мир живых – но не даром.' FROM `npc_text` b WHERE b.`id`=6491 AND BINARY b.`text0_0`=BINARY 'It is not yet your time. I shall aid your journey back to the realm of the living... for a price.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 6789,'У меня достаточно припасов, чтобы повысить наших бойцов до ветеранов.' FROM `npc_text` b WHERE b.`id`=6789 AND BINARY b.`text0_1`=BINARY 'I have enough supplies to upgrade our troops to veterans.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 8060,'Как раз вовремя, $c. Чувствуешь, как дрожит земля под ногами?$B$BИз улья что-то приближается. Встань рядом с пехотинцами, $N. Я на тебя рассчитываю!' FROM `npc_text` b WHERE b.`id`=8060 AND BINARY b.`text0_1`=BINARY 'You\'re just in time, $c.  Do you feel the ground shaking beneath you?$B$BSomething approaches from the hive.  Take a place near the grunts, $N.  I\'m counting on you!' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 8263,'Мы, орки, обычно скрытны, но в последнее время никто не скрывает своих чувств.' FROM `npc_text` b WHERE b.`id`=8263 AND BINARY b.`text0_1`=BINARY 'We orcs are usually a private people, but lately, no one\'s been hiding their feelings.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 8326,'Перед твоими глазами изображения, формы и знаки складываются в единое целое. Книга словно знает твое мастерство в кожевенном деле и предлагает выбор. Но помни: выбрать можно лишь один раз, и потом передумать уже не удастся!:' FROM `npc_text` b WHERE b.`id`=8326 AND BINARY b.`text0_1`=BINARY 'The assortment of images, shapes, and markings come together before your eyes. The book seems to know your skill with leatherworking and offers you a choice - but be warned - you may only select one and once you have done so, may not change your mind!:' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 8327,'Я не могу обучить тебя кожевничеству с использованием драконьей чешуи, $N. Тебе нужно отправиться в Танарис и найти дом Нарайна Причудня. Там загляни в книгу «Прорицание для чайников».' FROM `npc_text` b WHERE b.`id`=8327 AND BINARY b.`text0_1`=BINARY 'I cannot teach you dragonscale leatherworking, $N. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book "Soothsaying for Dummies."' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 8975,'Ну и провал! Будем считать это репетицией, ладно? Как насчет еще одной попытки?' FROM `npc_text` b WHERE b.`id`=8975 AND BINARY b.`text0_1`=BINARY 'Wow, you totally bombed out there. Let\'s think of that as a rehearsal, shall we? Ready to go out again?' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 9064,'Маршал Винздор тебя ждет, $N. К сожалению, сейчас он не может тебя принять. Он должен скоро вернуться.' FROM `npc_text` b WHERE b.`id`=9064 AND BINARY b.`text0_1`=BINARY 'Marshal Windsor has been expecting you, $N. Unfortunately, he is currently indisposed. He should be returning shortly.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 10128,'СТОЙ, $c! Следующего босса нужно искать не здесь. Попробуй пойти другим путем.' FROM `npc_text` b WHERE b.`id`=10128 AND BINARY b.`text0_0`=BINARY 'WAIT $c! Your search for the next boss isn\'t this way. Try another way.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 10830,'На этого... субъекта поступали жалобы. Говорят, он занимается темными делишками. Я здесь, чтобы выяснить, законно ли он ведет свои дела... и принять меры, если это не так.' FROM `npc_text` b WHERE b.`id`=10830 AND BINARY b.`text0_1`=BINARY 'There have been some complaints filed about this... individual. I\'m told he\'s something of a shady character. I am here to determine whether or not this business of his is legitimate... and take action if it proves otherwise.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`) SELECT 11492,'Добро пожаловать на Остров Терамор. Я могу помочь тебе что-нибудь найти?' FROM `npc_text` b WHERE b.`id`=11492 AND BINARY b.`text1_0`=BINARY 'Welcome to Theramore Isle. Something I can help you find?' ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='',VALUES(`text1_0_loc8`),`text1_0_loc8`);
