INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 13579,'Это портал на поле боя "Ущелье Песни Войны".' FROM `npc_text` b WHERE b.`id`=13579 AND BINARY b.`text0_1`=BINARY 'This is a portal to the Warsong Gulch battleground.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 19513,'Здесь пиво!' FROM `npc_text` b WHERE b.`id`=19513 AND BINARY b.`text0_0`=BINARY 'Brew here!' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 19526,'Мяса не желаешь? У меня тут его полно.$b$bНа гриле, я имею в виду.' FROM `npc_text` b WHERE b.`id`=19526 AND BINARY b.`text0_0`=BINARY 'Looking for meat? I\'ve got plenty right here.$b$bOn my grill, I mean.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 20564,'Принято. Докладывай обстановку, солдат.' FROM `npc_text` b WHERE b.`id`=20564 AND BINARY b.`text0_1`=BINARY 'Copy, Status report, Soldier.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 20618,'Привет, друг. Есть хочешь?' FROM `npc_text` b WHERE b.`id`=20618 AND BINARY b.`text0_0`=BINARY 'Hello, friend, Hungry?' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 20620,'Да?' FROM `npc_text` b WHERE b.`id`=20620 AND BINARY b.`text0_0`=BINARY 'Yes?' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 20621,'Вкусно пахнет, правда?' FROM `npc_text` b WHERE b.`id`=20621 AND BINARY b.`text0_0`=BINARY 'It smells delicious, doesn\'t it?' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 20622,'Тебе что-нибудь нужно?' FROM `npc_text` b WHERE b.`id`=20622 AND BINARY b.`text0_0`=BINARY 'Did you need something?' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 22990,'Будьте осторожны, друзья. Предатель уединился во дворе неподалеку отсюда.' FROM `npc_text` b WHERE b.`id`=22990 AND BINARY b.`text0_1`=BINARY 'Be wary, friends. The Betrayer meditates in the court just beyond.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 30000,'Здесь ты найдешь учителя начертания.' FROM `npc_text` b WHERE b.`id`=30000 AND BINARY b.`text0_0`=BINARY 'Here you will find the Inscription Trainer.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 30000,'Здесь ты найдешь учителя начертания.' FROM `npc_text` b WHERE b.`id`=30000 AND BINARY b.`text0_1`=BINARY 'Here you will find the Inscription Trainer.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 38927,'Не впервые мне приходится по самые зубы увязнуть в джунглях, которые взяли и набросились на меня. Мне довелось побывать по всему миру, $gсынок:милая;, и пусть меня свиньи затопчут, если эти джунгли станут моим концом.' FROM `npc_text` b WHERE b.`id`=38927 AND BINARY b.`text0_0`=BINARY 'This ain\'t the first time I been stuck up to me teef in a jungle that up an\' done ambushed me. I been all over the world, $gson:missy;, an\' I\'ll be hog-smacked if this one\'s gonna be the end of me.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 38961,'Здесь в Степях можно отлично поохотиться, если кишка у тебя не тонка.' FROM `npc_text` b WHERE b.`id`=38961 AND BINARY b.`text0_0`=BINARY 'There\'s some good huntin\' to be found here in the Barrens, if you\'ve the stomach for it.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 38963,'Капрал — хороший человек, но, когда речь заходит о приказах, он ничего вокруг не замечает.$B$BС этой землей происходит что-то неестественное, $n. Здесь не должно быть джунглей!' FROM `npc_text` b WHERE b.`id`=38963 AND BINARY b.`text0_0`=BINARY 'The Corporal\'s a good man, but he\'s got tunnel-vision when it comes to his orders.$B$BSomething unnatural is happening to the land here, $n. This jungle shouldn\'t be here!' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 50000,'Земля была щедра к нашему народу, $c. Мы должны быть благодарны за эту удачу.' FROM `npc_text` b WHERE b.`id`=50000 AND BINARY b.`text0_0`=BINARY 'The land has been good to our people, $c. We must be thankful for our good fortune.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 53245,'Я здесь, чтобы попросить помощи у знаменитой Аисы Воспевающей Облака, но никак не решаюсь прервать ее упражнения. Она такая собранная, такая умелая... такая красивая.' FROM `npc_text` b WHERE b.`id`=53245 AND BINARY b.`text0_0`=BINARY 'I came to ask the famous Aysa Cloudsinger for help, but I just can\'t bring myself to intrude on her exercises. She\'s so poised, so practiced... so beautiful.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) SELECT 62445,'Попробуй фирменное блюдо.' FROM `npc_text` b WHERE b.`id`=62445 AND BINARY b.`text0_1`=BINARY 'Should try the special.' ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='',VALUES(`text0_1_loc8`),`text0_1_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 65901,'Кто бы ни сказал, что лучше зажечь свечу, чем проклинать тьму...$b$bЧто ж, вряд ли этому человеку довелось зажечь столько свечей, сколько мне.' FROM `npc_text` b WHERE b.`id`=65901 AND BINARY b.`text0_0`=BINARY 'Whoever said they\'d rather light a candle than curse the darkness...$b$bWell, they probably haven\'t lit as many candles as me.' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) SELECT 65910,'Говорят: «Повернись лицом к солнцу, и тени останутся позади».$b$bНадеюсь, впереди тебя ждет много светлых дней, $n!' FROM `npc_text` b WHERE b.`id`=65910 AND BINARY b.`text0_0`=BINARY 'It is said, "Turn your face towards the sun, and the shadows will fall behind you."$b$bI hope you find many bright days ahead of you, $n!' ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='',VALUES(`text0_0_loc8`),`text0_0_loc8`);
